import re


_JOB_PATTERN = re.compile(
    r"JOB\s+(?P<name>\S+)\s+"
    r"AT\s+(?P<hour>[01]\d|2[0-3]):(?P<minute>[0-5]\d)\s+"
    r"RUN\s+(?P<script>\S+\.crms)"
    r"(?:\s+ON_ERROR\s+(?P<policy>ABORT|CONTINUE|RETRY:(?P<retries>\d+)))?"
)


def parse_schedule(cfg_text: str) -> list[dict]:
    """Parse a Meridian CRM batch schedule without performing any I/O."""
    schedule: list[dict] = []

    for line_number, raw_line in enumerate(cfg_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        match = _JOB_PATTERN.fullmatch(line)
        if match is None:
            raise ValueError(f"Invalid schedule line {line_number}: {raw_line!r}")

        clause = match.group("policy")
        if clause is None or clause == "ABORT":
            on_error = {"policy": "ABORT", "retries": 0}
        elif clause == "CONTINUE":
            on_error = {"policy": "CONTINUE", "retries": 0}
        else:
            on_error = {
                "policy": "RETRY",
                "retries": int(match.group("retries")),
            }

        schedule.append(
            {
                "name": match.group("name"),
                "at": f"{match.group('hour')}:{match.group('minute')}",
                "script": match.group("script"),
                "on_error": on_error,
            }
        )

    return schedule
